'use strict';
function barcodeHTML(value){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');try{JsBarcode(svg,value,{format:'CODE128',width:2,height:72,margin:14,displayValue:true,fontSize:16,font:'Arial',background:'#ffffff',lineColor:'#172d28'});const w=svg.getAttribute('width'),h=svg.getAttribute('height');svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.setAttribute('width','100%');svg.setAttribute('height','100%');svg.setAttribute('role','img');svg.setAttribute('aria-label','باركود بطاقة العميل');return svg.outerHTML;}catch{return '<p>تعذر توليد الباركود.</p>';}}
function programSummary(c){const p=Loyalty.program(c);return p.type==='points'?`${fmt(p.pointsPerVisit)} نقاط لكل زيارة · ${fmt(p.pointsCost)} نقطة = ${Loyalty.label(c)}`:`${fmt(c.target)} زيارات = ${Loyalty.label(c)}`;}
function codeHTML(c,m){return Loyalty.program(c).barcodeFormat==='code128'?barcodeHTML(m.id):qr(memberCode(m));}
cardHTML=function(c,m=null,full=false){const p=Loyalty.program(c),preview=m||{stamps:2,points:Math.floor(p.pointsCost*.4),rewards:0,name:'معاينة البطاقة',id:'RJ-PREVIEW01'},balance=p.type==='points'?(preview.points||0):(preview.stamps||0),goal=p.type==='points'?p.pointsCost:c.target,ready=Loyalty.available(preview,c);return `<div class="loyalty-card ${c.pattern?'pattern':''}" style="--card:${esc(c.color)};--accent:${esc(c.accent)}">${c.background?`<img class="card-background" src="${esc(c.background)}" alt="">`:''}<div class="card-top"><div class="actions"><div class="card-logo">${c.logo?`<img src="${esc(c.logo)}" alt="شعار النشاط" style="width:100%;height:100%;border-radius:12px;object-fit:contain">`:icon(c.icon)}</div><div><div class="card-brand">${esc(c.name)}</div><div class="card-category">${esc(c.category)}</div></div></div><span class="card-tag">رِجعة</span></div><div class="program-tag">${p.type==='points'?'بطاقة نقاط':p.type==='discount'?'بطاقة خصومات':'بطاقة زيارات'}</div><div class="card-title">${p.type==='points'?'رصيد نقاطك':'رصيد زياراتك'}</div><div class="card-count">${fmt(balance)} <small>${p.type==='points'?'نقطة':'من '+fmt(goal)}</small></div>${p.type==='points'?`<div class="points-progress" role="progressbar" aria-valuemin="0" aria-valuemax="${goal}" aria-valuenow="${Math.min(balance,goal)}"><span style="width:${Math.min(100,balance/goal*100)}%"></span></div><p class="points-note">${fmt(p.pointsPerVisit)} نقاط لكل زيارة مؤهلة</p>`:`<div class="stamps">${Array.from({length:c.target},(_,i)=>`<span class="stamp ${i<balance?'filled':''}">${c.stampImage?`<img class="stamp-image" src="${esc(c.stampImage)}" alt="ختم">`:icon(c.icon)}</span>`).join('')}</div>`}<div class="card-reward">${ready?`${icon('gift')} لديك ${fmt(ready)} مكافأة جاهزة`:`${esc(Loyalty.label(c))} ${p.type==='points'?'مقابل '+fmt(goal)+' نقطة':'بعد '+fmt(goal)+' زيارات'}`}</div>${full?`<div class="card-divider"></div><div class="${p.barcodeFormat==='code128'?'card-barcode':'card-qr'}">${codeHTML(c,preview)}</div><div class="card-member">${esc(preview.name||'عضو رِجعة')} · ${esc(preview.id)}</div>${m?'<button class="card-code-expand" data-action="expand-code">عرض الرمز كاملًا</button>':''}`:`<div class="card-divider"></div><div class="card-footer"><span>${m?.name?esc(m.name):'بطاقة الولاء'}</span><span>${ready?'مكافأتك بانتظارك':fmt(Math.max(0,goal-balance))+(p.type==='points'?' نقطة للمكافأة':' زيارات للمكافأة')}</span></div>`}</div>`;};
function mediaField(key,id,label){return `<div class="field"><span>${label}</span><div id="media-${key}" class="media-preview"></div><label class="upload-control"><span>اختر صورة</span><input id="${id}" type="file" accept="image/png,image/jpeg,image/webp" aria-label="رفع ${label}"></label><small>PNG أو JPG أو WebP · حتى ٥ ميجابايت</small></div>`;}
designHTML=function(){draft??=structuredClone(shop().card);draft.program=Loyalty.program(draft);const p=draft.program;return head('الهوية وقواعد الولاء','ابنِ بطاقة تناسب نشاطك','اختر البرنامج ثم صمّم البطاقة. التغييرات تظهر مباشرة.',`<button class="btn primary" data-action="save-card">${icon('check')} حفظ البطاقة</button>`)+`<div class="editor-grid"><section class="panel"><div class="editor-section"><div class="section-title"><span class="section-number">١</span><h2>نظام الولاء</h2></div><div class="program-options">${[['visits','coffee','زيارات','زيارات مدفوعة ثم هدية'],['discount','gift','خصم','خصم بعد اكتمال الزيارات'],['points','star','نقاط','نقاط لكل زيارة ومكافأة']].map(([type,i,t,sub])=>`<button class="program-option ${p.type===type?'active':''}" data-action="program-type" data-type="${type}" aria-pressed="${p.type===type}">${icon(i)}<strong>${t}</strong><small>${sub}</small></button>`).join('')}</div><div class="form-row mt">${p.type==='points'?`<label class="field"><span>نقاط لكل زيارة</span><input class="input" type="number" min="1" max="10000" step="1" data-program="pointsPerVisit" value="${p.pointsPerVisit}"></label><label class="field"><span>النقاط المطلوبة للمكافأة</span><input class="input" type="number" min="1" max="1000000" step="1" data-program="pointsCost" value="${p.pointsCost}"></label>`:`<label class="field"><span>عدد الزيارات للمكافأة</span><select data-card="target">${Array.from({length:11},(_,i)=>i+2).map(n=>`<option value="${n}" ${draft.target===n?'selected':''}>${fmt(n)} زيارات</option>`).join('')}</select></label>`}${p.type!=='discount'?`<label class="field"><span>المكافأة</span><input class="input" data-card="reward" value="${esc(draft.reward)}" maxlength="45"></label>`:''}</div>${p.type==='discount'?`<div class="form-row"><label class="field"><span>نوع الخصم</span><select data-program="discountType"><option value="percent" ${p.discountType==='percent'?'selected':''}>نسبة مئوية</option><option value="amount" ${p.discountType==='amount'?'selected':''}>مبلغ بالريال</option></select></label><label class="field"><span>قيمة الخصم</span><input class="input" type="number" data-program="discountValue" min="0.01" max="${p.discountType==='percent'?100:100000}" step="0.01" value="${p.discountValue}"></label></div>`:''}<div class="notice" id="program-example">${esc(programSummary(draft))}${p.type==='points'?'<br>تُخصم النقاط عند استخدام المكافأة، وتبقى النقاط الإضافية محفوظة.':p.type==='discount'?'<br>الموظف يسجل صرف الخصم؛ تطبيقه على الفاتورة يتم في الكاشير.':''}</div></div><div class="editor-section"><div class="section-title"><span class="section-number">٢</span><h2>هوية البطاقة</h2></div><label class="field"><span>اسم النشاط على البطاقة</span><input class="input" data-card="name" maxlength="36" value="${esc(draft.name)}"></label><label class="field"><span>نوع النشاط</span><select data-card="category">${['كافيه','مغسلة سيارات','متجر','صالون','حلاق','مطعم','نشاط آخر'].map(c=>`<option ${draft.category===c?'selected':''}>${c}</option>`).join('')}</select></label>${mediaField('logo','logo-file','شعار النشاط')}<div class="form-row"><label class="field"><span>لون البطاقة</span><input type="color" value="${draft.color}" data-card="color" aria-label="لون البطاقة"></label><label class="field"><span>لون الأختام والرصيد</span><input type="color" value="${draft.accent}" data-card="accent" aria-label="لون الرصيد"></label></div><div class="field"><span>أيقونة البرنامج</span><div class="icon-options">${[['coffee','قهوة'],['car','سيارة'],['bag','تسوق'],['scissors','حلاق'],['star','نجمة'],['heart','قلب']].map(([i,t])=>`<button class="icon-choice ${draft.icon===i?'active':''}" data-action="card-icon" data-icon="${i}" aria-label="${t}">${icon(i)}</button>`).join('')}</div></div><div class="field"><span>خلفية البطاقة</span><div class="segmented"><button class="${!draft.pattern?'active':''}" data-action="pattern" data-value="plain">سادة</button><button class="${draft.pattern?'active':''}" data-action="pattern" data-value="dots">نقشة خفيفة</button></div></div>${mediaField('background','background-file','صورة خلفية مخصصة')}${mediaField('stampImage','stamp-file','صورة ختم مخصصة')}</div><div class="editor-section"><div class="section-title"><span class="section-number">٣</span><h2>الرمز والشروط</h2></div><label class="field"><span>طريقة عرض الرمز</span><select data-program="barcodeFormat"><option value="qr" ${p.barcodeFormat==='qr'?'selected':''}>رمز QR مربع</option><option value="code128" ${p.barcodeFormat==='code128'?'selected':''}>باركود Code 128 بعرض البطاقة</option></select><small>الباركود يعرّف العميل. تسجيل الزيارة يتم من واجهة الموظف.</small></label><label class="field"><span>شروط البرنامج</span><textarea data-card="terms" rows="3" maxlength="600">${esc(draft.terms)}</textarea></label><div class="notice">مع وجود رصيد أو مكافآت للعملاء، لا يمكن تغيير قواعد احتساب الرصيد. يمكنك تعديل شكل البطاقة والرمز.</div></div></section><aside class="editor-preview"><h3>معاينة مباشرة · البطاقة كاملة</h3><div id="card-preview">${cardHTML(draft,null,true)}</div><p class="preview-note">معاينة داخل الموقع. ترتيب البطاقة في المحافظ يعتمد على قالب المحفظة.</p></aside></div>`;};
function refreshMedia(){for(const key of ['logo','background','stampImage']){const el=document.querySelector('#media-'+key);if(el)el.innerHTML=draft[key]?`<div class="uploaded-image"><img src="${esc(draft[key])}" alt="${key==='logo'?'شعار النشاط':'الصورة المرفوعة'}"><button type="button" class="image-remove" data-action="media-remove" data-key="${key}" aria-label="إزالة ${key==='logo'?'الشعار':key==='background'?'الخلفية':'صورة الختم'}">×</button></div>`:'<p class="line-meta">لم تُرفع صورة بعد.</p>';}}
updatePreview=function(){const el=document.querySelector('#card-preview');if(el)el.innerHTML=cardHTML(draft,null,true);const example=document.querySelector('#program-example');if(example)example.textContent=programSummary(draft);refreshMedia();};
bindEditor=function(){refreshMedia();document.querySelectorAll('[data-card]').forEach(el=>el.addEventListener('input',()=>{draft[el.dataset.card]=el.dataset.card==='target'?Number(el.value):el.value;updatePreview();}));document.querySelectorAll('[data-program]').forEach(el=>el.addEventListener('input',()=>{draft.program[el.dataset.program]=['pointsPerVisit','pointsCost','discountValue'].includes(el.dataset.program)?Number(el.value):el.value;if(draft.program.type==='discount')draft.reward=Loyalty.label(draft);updatePreview();}));for(const [id,key] of [['logo-file','logo'],['background-file','background'],['stamp-file','stampImage']]){const input=document.getElementById(id);input?.addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>5242880){toast('اختر صورة PNG أو JPG أو WebP حتى ٥ ميجابايت.');input.value='';return;}const generation=crypto.randomUUID();input.dataset.generation=generation;try{const value=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(f);});const img=new Image();img.src=value;await img.decode();if(!img.naturalWidth||input.dataset.generation!==generation||!input.isConnected)return;draft[key]=value;updatePreview();}catch{toast('الصورة تالفة أو غير قابلة للعرض.');input.value='';}});}};
mutationActions.add('program-type');mutationActions.add('media-remove');
window.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='program-type'||action==='media-remove'){e.preventDefault();e.stopImmediatePropagation();if(!canOperate()){toast('يلزم تفعيل الاشتراك.');return;}if(action==='program-type'){draft.program={...Loyalty.program(draft),type:b.dataset.type};if(draft.program.type==='discount')draft.reward=Loyalty.label(draft);else if(draft.reward.startsWith('خصم '))draft.reward='هدية مجانية';render();}else{draft[b.dataset.key]='';const inp=document.getElementById(({logo:'logo-file',background:'background-file',stampImage:'stamp-file'})[b.dataset.key]);if(inp){inp.value='';inp.dataset.generation='removed';}updatePreview();}return;}if(action==='save-card'){try{draft.program=Loyalty.validate(draft);if(draft.program.type==='discount')draft.reward=Loyalty.label(draft);if(Loyalty.ruleKey(draft)!==Loyalty.ruleKey(shop().card)&&shop().members.some(Loyalty.protectedBalance))throw Error('يوجد رصيد أو مكافآت للعملاء. لا يمكن تغيير قواعد البرنامج الحالي.');}catch(error){e.preventDefault();e.stopImmediatePropagation();toast(error.message);}}if(action==='expand-code'){e.preventDefault();e.stopImmediatePropagation();const m=currentMember();if(m)modal('رمز بطاقة العميل',`<div class="expanded-code ${Loyalty.program(shop().card).barcodeFormat==='qr'?'square':''}">${codeHTML(shop().card,m)}</div><p class="sub" style="text-align:center">ارفع سطوع الشاشة واعرض الرمز للموظف.</p>`);}},true);
const visitsScan=processScan;
processScan=async function(raw){if(serverMode)return visitsScan(raw);if(!canOperate()){toast('يلزم تفعيل الاشتراك.');return;}const s=shop(),e=s.employees.find(e=>e.id===staffEmployee&&e.status==='active');if(!e){toast('اختر موظفًا نشطًا.');return;}let id=String(raw).trim();if(id.startsWith('RIJAA:')){const parts=id.split(':');if(parts[1]!==s.id){toast('البطاقة تخص نشاطًا آخر.');return;}id=parts[2];}const m=s.members.find(m=>m.id===id);if(!m){toast('البطاقة غير موجودة في هذا النشاط.');return;}try{const result=Loyalty.apply(m,s.card,staffMode),tx={id:crypto.randomUUID(),member:m.id,name:m.name||m.phone,type:staffMode,employee:e.name,time:Date.now(),points:result.points,programType:Loyalty.program(s.card).type,pointsAdded:Loyalty.program(s.card).type==="points"?Loyalty.program(s.card).pointsPerVisit:0,reward:result.reward};s.logs.unshift(tx);lastTx={...tx,...result,shop:s.id,undone:false};selectedStaffMember=m.id;save();scannerLock=true;if(stream){document.querySelector('#scan-status').textContent=staffMode==='stamp'?'تمت إضافة الرصيد':'تم صرف المكافأة';toast('تم تسجيل العملية.');}else render();}catch(error){toast(error.message);}};
const previousRender=render;render=function(){previousRender();const s=shop();if(!s||publicPage)return;const p=Loyalty.program(s.card);if(role==='staff'&&view==='scan'){document.querySelectorAll('[data-action="staff-mode"][data-mode="stamp"]').forEach(el=>el.textContent=p.type==='points'?'إضافة نقاط':'إضافة زيارة');const title=document.querySelector('#scan-title');if(title&&staffMode==='stamp')title.textContent=p.type==='points'?`جاهز لإضافة ${fmt(p.pointsPerVisit)} نقاط`:'جاهز لإضافة زيارة';const simulation=document.querySelector('[data-action="simulate-scan"]');if(simulation&&staffMode==='stamp')simulation.textContent=p.type==='points'?'محاكاة مسح وإضافة نقاط':'محاكاة مسح وإضافة زيارة';const select=document.querySelector('#staff-member');if(select)Array.from(select.options).forEach(o=>{const m=s.members.find(m=>m.id===o.value);if(m)o.textContent=`${m.name||m.phone} · ${fmt(p.type==='points'?m.points||0:m.stamps)} ${p.type==='points'?'نقاط':'أختام'} · ${fmt(Loyalty.available(m,s.card))} مكافآت`;});if(lastTx){const heading=document.querySelector('.scanner-result h2');if(heading&&lastTx.type==='stamp')heading.textContent=p.type==='points'?'تمت إضافة النقاط':'تمت إضافة الزيارة';const result=document.querySelector('.scanner-result .sub');if(result)result.textContent=lastTx.type==='redeem'?`${lastTx.name} · ${lastTx.reward?.label||Loyalty.label(s.card)}`:`${lastTx.name} · ${fmt(p.type==='points'?lastTx.points||0:lastTx.stamps)} ${p.type==='points'?'نقاط':'زيارات'}`;}}if(view==='customers'){const rows=document.querySelector('#customer-rows');if(rows)rows.innerHTML=programCustomerRows(s.members);const headers=document.querySelectorAll('th');if(headers[2])headers[2].textContent=p.type==='points'?'رصيد النقاط':'الأختام';}if(role==='owner'&&view==='overview'){const subtitle=document.querySelector('.grid-two>section:last-child .panel-head p');if(subtitle)subtitle.textContent=programSummary(s.card);const stats=document.querySelectorAll('.stat-value');if(stats[2])stats[2].textContent=fmt(s.members.reduce((n,m)=>n+Loyalty.available(m,s.card),0));}if(role==='client'){if(clientStage==='phone'){const info=document.querySelector('.phone-header p');if(info)info.textContent=programSummary(s.card);}document.querySelectorAll('.journey-intro>p').forEach(el=>el.textContent=programSummary(s.card));}};
function programCustomerRows(members){const p=Loyalty.program(shop().card);return members.length?members.map(m=>`<tr><td><div class="cell-person"><span class="avatar">${icon('users')}</span><div>${esc(m.name)}<small>${esc(m.id)}</small></div></div></td><td dir="ltr" style="text-align:right">${esc(m.phone)}</td><td>${fmt(p.type==='points'?m.points||0:m.stamps)}${p.type==='points'?'':' / '+fmt(shop().card.target)}</td><td><span class="pill ${Loyalty.available(m,shop().card)?'gold':'gray'}">${fmt(Loyalty.available(m,shop().card))}</span></td><td><button class="btn quiet small" data-action="member-card" data-id="${m.id}">عرض</button></td></tr>`).join(''):'<tr><td colspan="5" class="empty">لا توجد نتائج.</td></tr>';}
customerRows=programCustomerRows;
logsHTML=function(logs,limit=50){return logs.length?`<div class="activity">${logs.slice(0,limit).map(l=>{const caption=l.type==='redeem'?`صرف ${l.reward?.label||'مكافأة'}`:l.type==='undo'?'تراجع عن العملية':l.type==='reward'?'استحقاق مكافأة':l.programType==='points'?`إضافة ${fmt(l.pointsAdded)} نقاط`:'إضافة زيارة';return `<div class="activity-row"><span class="avatar">${icon(l.type==='redeem'?'gift':l.programType==='points'?'star':'coffee')}</span><div class="grow"><strong>${esc(l.name)}</strong><small>${esc(l.employee)}${l.shopName?' · '+esc(l.shopName):''}</small></div><div><b>${esc(caption)}</b><div class="line-meta">${new Date(l.time).toLocaleTimeString('ar-SA',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Riyadh'})} · ${new Date(l.time).toLocaleDateString('ar-SA',{month:'short',day:'numeric',timeZone:'Asia/Riyadh'})}</div></div></div>`;}).join('')}</div>`:'<div class="empty">لا توجد عمليات بعد.</div>';};
render();


